/**
 * The public video gallery (docs/23): formats anyone can ask their AI for, and videos founders made with them.
 *
 * - Formats and styles come from `formats.json`, generated by `scripts/build_plugin.py` from the Studio's
 *   recipes and styles (the same words the MCP and the plugin serve). Never edit that file by hand.
 * - Videos are listed in `videos.ts`. Deno never hosts a video: an entry is a link to where its maker posted it.
 */
import data from './formats.json';
import { VIDEOS, type GalleryVideo } from './videos';

export type { GalleryVideo };
export { VIDEOS };

export type Format = {
  slug: string;
  title: string;
  summary: string;
  tags: string[];
  ratio: string;
  /** Length in seconds; 0 or null for stills (a carousel). */
  seconds: number | null;
  style: string;
  body: string;
};

export type Style = { slug: string; title: string; summary: string; tags: string[]; best_for: string; avoid_for: string };

export const FORMATS: Format[] = data.recipes;
export const STYLES: Style[] = data.styles;

export const findFormat = (slug: string) => FORMATS.find((f) => f.slug === slug);
export const findStyle = (slug: string) => STYLES.find((s) => s.slug === slug);
export const findVideo = (slug: string) => VIDEOS.find((v) => v.slug === slug);

export const formatHref = (slug: string) => `/videos/formats/${slug}`;
export const videoHref = (slug: string) => `/videos/${slug}`;

export const isStill = (f: Format) => !f.seconds;

/** "16:9 · 32 s · Living UI" */
export function formatMeta(f: Format): string {
  const style = findStyle(f.style)?.title ?? f.style;
  return [f.ratio, isStill(f) ? 'Stills' : `${f.seconds} s`, style].filter(Boolean).join(' · ');
}

/**
 * The prompt a founder pastes into their AI to get this format. It names the recipe and the style, so the AI
 * loads the right rules from Deno instead of guessing.
 */
export function formatPrompt(f: Format, styleSlug: string = f.style): string {
  const style = findStyle(styleSlug);
  const what = isStill(f) ? `a ${f.title}` : `a ${f.title} video`;
  return [
    `Make ${what} for my validated idea with Deno Studio.`,
    '',
    `- Format: the "${f.slug}" recipe (search_recipes).${f.ratio ? ` ${f.ratio}${isStill(f) ? '.' : `, about ${f.seconds} seconds.`}` : ''}`,
    `- Style: "${style?.slug ?? styleSlug}" (get_style).`,
    '- Use only my real facts from get_founder_context: pains with sources, my stories, my brand kit. Do not invent numbers, quotes or features.',
    '',
    'Ask me the five pre-production questions in one message, each with your suggested answer. Then show me the treatment and wait for my "go" before you build.',
  ].join('\n');
}

/** An embeddable player for a YouTube or Vimeo link; null for anything else (X, LinkedIn: we link out). */
export function embedUrl(url: string): string | null {
  try {
    const u = new URL(url);
    if (u.protocol !== 'https:') return null;
    const host = u.hostname.replace(/^(www|m)\./, '');
    if (host === 'youtu.be' || host === 'youtube.com') {
      const id = host === 'youtu.be' ? u.pathname.slice(1) : (u.searchParams.get('v') ?? u.pathname.match(/^\/(?:shorts|embed|live)\/([\w-]+)/)?.[1] ?? '');
      return /^[\w-]{6,20}$/.test(id) ? `https://www.youtube-nocookie.com/embed/${id}` : null;
    }
    if (host === 'vimeo.com') {
      const m = u.pathname.match(/^\/(\d+)(?:\/(\w+))?/);
      return m ? `https://player.vimeo.com/video/${m[1]}${m[2] ? `?h=${m[2]}` : ''}` : null;
    }
  } catch {
    return null;
  }
  return null;
}

/** A YouTube link's own thumbnail; null for other hosts (the card then draws the format's colour block). */
export function posterUrl(v: GalleryVideo): string | null {
  if (v.poster) return v.poster;
  const id = embedUrl(v.url)?.match(/youtube-nocookie\.com\/embed\/([\w-]+)/)?.[1];
  return id ? `https://i.ytimg.com/vi/${id}/hqdefault.jpg` : null;
}

/** Where the video is posted, for the "Watch on …" link. */
export function hostName(url: string): string {
  try {
    const host = new URL(url).hostname.replace(/^(www|m)\./, '');
    if (host === 'youtu.be' || host === 'youtube.com') return 'YouTube';
    if (host === 'vimeo.com') return 'Vimeo';
    if (host === 'x.com' || host === 'twitter.com') return 'X';
    if (host === 'linkedin.com') return 'LinkedIn';
    return host;
  } catch {
    return 'the original post';
  }
}

export const videosForFormat = (slug: string) => VIDEOS.filter((v) => v.format === slug);

/** ISO 8601 duration for schema.org (PT32S). */
export const isoDuration = (seconds: number) => `PT${Math.max(1, Math.round(seconds))}S`;

/** Colour block per ratio family, so cards without a poster still look deliberate. */
export const FORMAT_TONE: Record<string, string> = {
  '16:9': 'var(--lime)',
  '9:16': 'var(--peach)',
  '1:1': 'var(--blue-soft)',
  '4:5': 'var(--amber-soft)',
};
